import { ArrowRight, ImageIcon, Plus } from "lucide-react";
import Image from "next/image";
import Link from "next/link";

import { formatDuration, formatPrice, imageZoom } from "@/lib/catalog";
import type { AdminEntityListItem } from "@/lib/types";

export function AdminEntityList({
  items,
  kind,
}: {
  items: AdminEntityListItem[];
  kind: "characters" | "shows";
}) {
  const base = kind === "characters" ? "/admin/catalog/characters" : "/admin/show-programs";
  return (
    <>
      <div className="admin-list-toolbar">
        <div><strong>{items.length}</strong><span>{kind === "characters" ? "активных персонажей" : "активных шоу-программ"}</span></div>
        <Link className="button button-violet" href={`${base}/new`}><Plus size={18} /> Добавить</Link>
      </div>
      <div className="admin-entity-grid">
        {items.map((item) => (
          <Link href={`${base}/${item.id}`} key={item.id}>
            <div className="admin-entity-media">
              {item.hero_file_path ? <Image src={item.hero_file_path} alt="" fill sizes="240px" style={{ objectFit: item.cover_fit, objectPosition: `${item.cover_offset_x}% ${item.cover_offset_y}%`, transform: `scale(${imageZoom(item)})`, transformOrigin: `${item.cover_offset_x}% ${item.cover_offset_y}%` }} unoptimized /> : <ImageIcon />}
              <span className={`content-status status-${item.status}`}>{item.status}</span>
            </div>
            <div className="admin-entity-copy"><h2>{item.name}</h2><p>{kind === "shows" ? `${formatDuration(item.default_duration_minutes)} · ${formatPrice(item.base_price)}` : item.categories.filter((slug) => slug !== "all").join(" · ") || "Без категории"}</p><span>Открыть редактор <ArrowRight size={16} /></span></div>
          </Link>
        ))}
      </div>
    </>
  );
}
